// SLEEP STAGES from a model TRAINED ON SLEEP-LAB NIGHTS (v119).
//
// Training data: "Motion and heart rate from a wrist-worn wearable and labeled
// sleep from polysomnography" (Walch O., PhysioNet 2019,
// https://doi.org/10.13026/hmhs-py35; Walch et al., Sleep 2019,
// https://doi.org/10.1093/sleep/zsz180), Open Data Commons Attribution License
// v1.0 — 31 healthy adults, Apple Watch heart rate and wrist acceleration,
// every 30-s epoch scored from polysomnography.
//
// Model: gradient-boosted trees (150 rounds, depth 3; sleep_stage_gbt.g.dart,
// generated by m2cgen from scikit-learn) over 15 per-epoch features built only
// from what this band gives — 1 Hz heart rate and the 1 Hz gravity vector —
// then a 4-state Viterbi pass with the stage transitions and class shares
// measured on the same nights (prior tempered by α = 0.5).
//
// Held-out accuracy (5-fold, people never seen in training): 4-class Cohen's
// κ 0.41 pooled, 0.42 median per night; sleep/wake κ 0.51. For comparison:
// WHOOP 4.0 κ 0.37 (Schyvens 2025), WHOOP 3.0 κ 0.44 in young adults
// (Miller 2022), and the rule stager this replaces κ 0.13 (its own test).
// 31 nights is a small corpus; a larger licensed one replaces it later.
//
// The feature code below is a line-for-line port of the training script
// (tool/sleep_stage_training/sa_train.py); the parity test in
// test/sleep_stage_model_test.dart checks it against the Python output.
//
// Pure and isolate-safe.

import 'dart:math' as math;

import 'package:openstrap_analytics/onehz.dart' as ana;

import 'sleep_stage_gbt.g.dart' as gbt;

const int kStageEpochSec = 30;

/// Fewest observed epochs (1 h) before the model stages a night.
const int kStageModelMinEpochs = 120;

const List<String> kStageLabels = ['wake', 'light', 'deep', 'rem'];

/// Class shares on the training nights (W, light, deep, REM).
const List<double> kStagePrior = gbt.kTrainedPrior;

/// 30-s stage transition probabilities on the training nights (row = from).
const List<List<double>> kStageTransitions = gbt.kTrainedTransitions;

const double kStagePriorTemper = 0.5;

double _nanStat(List<double> s, double Function(List<double>) f) {
  final v = [for (final x in s) if (x.isFinite) x];
  return v.length >= 5 ? f(v) : double.nan;
}

double _sum(List<double> v) => v.fold(0.0, (a, b) => a + b);
double _mean(List<double> v) => _sum(v) / v.length;
double _std(List<double> v) {
  final m = _mean(v);
  var s = 0.0;
  for (final x in v) {
    s += (x - m) * (x - m);
  }
  return math.sqrt(s / v.length);
}

double _max(List<double> v) => v.reduce(math.max);

List<double> _roll(List<double> v, int w, double Function(List<double>) f) {
  final h = w ~/ 2;
  return [
    for (var i = 0; i < v.length; i++)
      () {
        final s = <double>[
          for (var j = math.max(0, i - h); j <= math.min(v.length - 1, i + h); j++)
            if (v[j].isFinite) v[j],
        ];
        return s.isEmpty ? double.nan : f(s);
      }(),
  ];
}

List<double> _scale(List<double> v) {
  final ok = [for (final x in v) if (x.isFinite) x]..sort();
  if (ok.length < 10) return List<double>.filled(v.length, double.nan);
  final lo = ana.percentileSorted(ok, 5)!;
  final med = ana.percentileSorted(ok, 50)!;
  final hi = ana.percentileSorted(ok, 95)!;
  final span = math.max(hi - lo, 1e-9);
  return [for (final x in v) (x - med) / span];
}

/// The 15 per-epoch features, row per epoch, NaN → 0 (as trained).
///
/// [hr] and [gravity] are per second from the window's first second: HR in
/// bpm (≤ 0 = none), gravity as (x, y, z) or null when absent.
List<List<double>> stageFeatures(
  List<double> hr,
  List<List<double>?> gravity,
  int nEpochs,
) {
  final secs = nEpochs * kStageEpochSec;
  final hr1 = [
    for (var i = 0; i < secs; i++)
      i < hr.length && hr[i] > 0 ? hr[i] : double.nan,
  ];
  final ang = [
    for (var i = 0; i < secs; i++)
      () {
        final g = i < gravity.length ? gravity[i] : null;
        if (g == null) return double.nan;
        return math.atan2(g[2], math.sqrt(g[0] * g[0] + g[1] * g[1])) *
            180 /
            math.pi;
      }(),
  ];
  final dang = [
    for (var i = 0; i < secs; i++)
      i == 0 ? double.nan : (ang[i] - ang[i - 1]).abs(),
  ];
  List<double> perEpoch(List<double> a, double Function(List<double>) f) => [
        for (var e = 0; e < nEpochs; e++)
          _nanStat(a.sublist(e * kStageEpochSec, (e + 1) * kStageEpochSec), f),
      ];
  final mot = [for (final v in perEpoch(dang, _sum)) math.log(1 + v)];
  final hre = perEpoch(hr1, _mean);
  final hrsd = perEpoch(hr1, _std);
  final hrs = _scale(hre);
  final roll21 = _roll(hre, 21, _mean);
  final t = [
    for (var e = 0; e < nEpochs; e++) nEpochs <= 1 ? 0.0 : e / (nEpochs - 1),
  ];
  final cols = <List<double>>[
    mot,
    _roll(mot, 5, _max),
    _roll(mot, 11, _mean),
    _roll(mot, 21, _mean),
    hrs,
    _roll(hrs, 5, _mean),
    _roll(hrs, 11, _mean),
    _roll(hrs, 21, _mean),
    _scale(_roll(hre, 11, _std)),
    _scale(_roll(hre, 21, _std)),
    _scale(hrsd),
    _scale([for (var e = 0; e < nEpochs; e++) hre[e] - roll21[e]]),
    t,
    [for (final x in t) math.exp(math.log(0.01) * x)],
    [for (final x in t) math.sin(math.pi * x)],
  ];
  return [
    for (var e = 0; e < nEpochs; e++)
      [for (final c in cols) c[e].isFinite ? c[e] : 0.0],
  ];
}

/// Per-epoch class probabilities (W, light, deep, REM).
List<List<double>> stageProbabilities(List<List<double>> features) =>
    [for (final f in features) gbt.score(f)];

/// Viterbi decode of [probs] with the trained transitions and the tempered
/// prior; returns class indices.
List<int> stageViterbi(List<List<double>> probs) {
  final n = probs.length;
  if (n == 0) return const [];
  final lT = [
    for (final r in kStageTransitions) [for (final p in r) math.log(p)],
  ];
  final lPrior = [for (final p in kStagePrior) math.log(p)];
  List<double> like(List<double> p) => [
        for (var s = 0; s < 4; s++)
          math.log(math.max(p[s], 1e-9)) - kStagePriorTemper * lPrior[s],
      ];
  var d = [for (var s = 0; s < 4; s++) like(probs[0])[s] + lPrior[s]];
  final back = List.generate(n, (_) => List<int>.filled(4, 0));
  for (var i = 1; i < n; i++) {
    final l = like(probs[i]);
    final nd = List<double>.filled(4, 0);
    for (var s = 0; s < 4; s++) {
      var best = double.negativeInfinity, arg = 0;
      for (var r = 0; r < 4; r++) {
        final v = d[r] + lT[r][s];
        if (v > best) {
          best = v;
          arg = r;
        }
      }
      nd[s] = best + l[s];
      back[i][s] = arg;
    }
    d = nd;
  }
  final path = List<int>.filled(n, 0);
  var best = double.negativeInfinity;
  for (var s = 0; s < 4; s++) {
    if (d[s] > best) {
      best = d[s];
      path[n - 1] = s;
    }
  }
  for (var i = n - 1; i > 0; i--) {
    path[i - 1] = back[i][path[i]];
  }
  return path;
}

/// Per-second 4-class labels over a sleep window, or null when too little of
/// it was observed (the caller keeps its base labels). Seconds the base
/// segmentation marked 'unobserved' stay unobserved.
List<String>? modelStageNight({
  required List<double> hr,
  required List<List<double>?> gravity,
  required List<String> baseStages4,
}) {
  final len = baseStages4.length;
  final nE = len ~/ kStageEpochSec;
  if (nE == 0) return null;
  var observed = 0;
  for (var e = 0; e < nE; e++) {
    var o = 0;
    for (var s = e * kStageEpochSec; s < (e + 1) * kStageEpochSec; s++) {
      if (baseStages4[s] != 'unobserved') o++;
    }
    if (o * 2 >= kStageEpochSec) observed++;
  }
  if (observed < kStageModelMinEpochs) return null;
  final path = stageViterbi(stageProbabilities(stageFeatures(hr, gravity, nE)));
  return [
    for (var s = 0; s < len; s++)
      baseStages4[s] == 'unobserved'
          ? 'unobserved'
          // The tail past the last whole epoch takes the last epoch's stage.
          : kStageLabels[path[math.min(s ~/ kStageEpochSec, nE - 1)]],
  ];
}
